#!/usr/bin/env python3

"""Test edge cases for infl of template variant extraction."""

from wikidict.render import parse_word

def test_multiple_infl_of_templates():
    """Test multiple infl of templates in one entry."""

    content = """==English==

===Verb===
{{head|en|verb form}}

# {{infl of|en|run||ing-form}}
# {{infl of|en|running||alternative-spelling}}
"""

    print("Testing multiple infl of templates:")
    word_data = parse_word("running", content, "en")
    print(f"  Variants: {word_data.variants}")
    print(f"  Definitions: {word_data.definitions}")

    # Should extract both 'run' and 'running' as variants
    expected_variants = {'run', 'running'}
    actual_variants = set(word_data.variants)

    if expected_variants <= actual_variants:
        print("✓ PASS: All expected variants found")
        return True
    else:
        missing = expected_variants - actual_variants
        print(f"✗ FAIL: Missing variants: {missing}")
        return False

def test_infl_of_with_different_forms():
    """Test infl of with different parameter arrangements."""

    # Test with different parameter patterns
    test_cases = [
        ("{{infl of|en|cling||ing-form}}", "cling"),  # Standard form
        ("{{infl of|en|go|went|past}}", "go"),        # With alternative form
        ("{{infl of|en|be||present|1=s}}", "be"),     # With numbered parameter
    ]

    all_passed = True
    for template, expected_variant in test_cases:
        content = f"""==English==

===Verb===
{{head|en|verb form}}

# {template}
"""
        print(f"Testing template: {template}")
        word_data = parse_word("test_word", content, "en")
        print(f"  Extracted variants: {word_data.variants}")

        if expected_variant in word_data.variants:
            print(f"✓ PASS: Found expected variant '{expected_variant}'")
        else:
            print(f"✗ FAIL: Expected variant '{expected_variant}' not found")
            all_passed = False
        print()

    return all_passed

if __name__ == "__main__":
    print("=== Edge Case Testing ===\n")

    result1 = test_multiple_infl_of_templates()
    print()
    result2 = test_infl_of_with_different_forms()

    if result1 and result2:
        print("🎉 All edge case tests passed!")
    else:
        print("❌ Some edge case tests failed.")

